/// One life's outlook over a span.
#[derive(Clone, Debug, uniffi::Record)]
#[allow(missing_docs)]
pub struct LifeOutlookRecord {
    pub life: String,
    /// 0–100.
    pub score: f64,
    pub band: String,
    pub trend: String,
    pub words: String,
    pub advice: String,
    pub best_at: Option<ExactInstant>,
    /// 0–100.
    pub best_score: f64,
    pub care_at: Option<ExactInstant>,
    /// 0–100.
    pub care_score: f64,
    pub why_expert: Vec<String>,
}

/// The outlook.
#[derive(Clone, Debug, uniffi::Record)]
#[allow(missing_docs)]
pub struct OutlookRecord {
    pub span: String,
    pub from: ExactInstant,
    pub to: ExactInstant,
    /// 0–100.
    pub score: f64,
    pub band: String,
    pub headline: String,
    pub lives: Vec<LifeOutlookRecord>,
    pub season: String,
    pub season_why: String,
}

#[uniffi::export]
impl Engine {
    /// The outlook for `span` (`day`, `week`, `month` or `year`) from `at`, in plain words.
    #[allow(clippy::too_many_arguments)]
    pub fn outlook(
        &self,
        birth: ExactInstant,
        birth_lat: f64,
        birth_lon: f64,
        lat: f64,
        lon: f64,
        system: HouseSystem,
        ayanamsa: AyanamsaChoice,
        span: String,
        at: ExactInstant,
        lang: String,
        focus: Vec<String>,
    ) -> Result<OutlookRecord, KshanaError> {
        let span = kshana_rules::Span::parse(&span).ok_or_else(|| KshanaError::Engine(format!("unknown span {span}")))?;
        let natal = self.natal(birth, birth_lat, birth_lon, system, ayanamsa)?;
        let obs = Observer { latitude_deg: lat, longitude_deg: lon, height_m: 0.0 };
        let o = kshana_rules::outlook_in(&self.spk, self.eop.as_ref(), &natal, &obs, to_house_system(system), ayanamsa.into(), span, at.into(), kshana_rules::Lang::parse(&lang), &focus_of(&focus))
            .map_err(|e| KshanaError::Engine(format!("{e:?}")))?;
        Ok(OutlookRecord {
            span: o.span.key().to_string(),
            from: o.from.into(),
            to: o.to.into(),
            score: o.score * 100.0,
            band: o.band.word().to_string(),
            headline: o.headline.clone(),
            lives: o
                .lives
                .iter()
                .map(|l| LifeOutlookRecord {
                    life: l.life.name().to_string(),
                    score: l.score * 100.0,
                    band: l.band.word().to_string(),
                    trend: l.trend.to_string(),
                    words: l.words.clone(),
                    advice: l.advice.clone(),
                    best_at: l.best_at.map(Into::into),
                    best_score: l.best_score * 100.0,
                    care_at: l.care_at.map(Into::into),
                    care_score: l.care_score * 100.0,
                    why_expert: l.why.clone(),
                })
                .collect(),
            season: o.season.clone(),
            season_why: o.season_why.clone(),
        })
    }
}

/// The plain-words audit: every engine call the app makes for a person, for three
/// people at three instants, read the way the person would read it. Any astrology word
/// in a sentence meant for them fails the test with the field and the sentence.
#[cfg(test)]
mod plain_audit {
    use super::*;

    /// Fields that carry keys, identifiers or the expert layer, never shown to the
    /// person on the common screens.
    const NOT_SHOWN: &[&str] = &[
        "lord", "planet", "graha", "kind", "key", "rule_id", "rule_ids", "source", "life", "band", "trend", "purpose",
        "verdict", "span", "dosha", "tara_name", "moon_star", "moon", "dasha", "lagna_sign", "houses", "sign", "sub",
        "star", "dasha_at_birth", "moon_a", "moon_b", "why_expert", "season_why", "kp_star", "kp_sub", "kp_sub_sub",
        "provenance_engine", "provenance_kernel", "provenance_models", "body", "body_a", "body_b", "aspect", "unit",
        "signature", "tithi", "nakshatra", "yoga", "hora", "factors", "cautions", "sub_lord", "agents", "ruling_planets",
        "moon_sub_lord", "question", "effort", "day", "mantra",
        // Expert-only remedy fields (the parihara expert page behind "Show the chart
        // pages"): the located cause in the texts' terms, karma class, dosha families,
        // the rung's claim, cadence, the ledger line and the hora/tithi windows.
        "cause_expert", "dignity", "running_level", "karma_class", "karma_kind", "karma_basis", "karma_source",
        "may_claim", "remedy_family", "offended", "ledger_hint", "cadence", "measurable",
        // The chart reason behind a remedy, shown only when the person taps "How this
        // helps" (asked for by the owner on 2026-10-20): it names the planet on purpose.
        "how_it_helps",
        // The yoga catalogue's expert layer (`yogas::ChartYogaRecord`): the condition in
        // the texts' terms, the family key and the activating dasha lords.
        "rule", "group", "lords",
        // Per-user technique comparison (learn.rs) and the birth-time witnesses: the
        // technique names and keys are for the expert view; `plain` and `name` are read.
        "technique_expert", "best_key", "witness_keys",
    ];

    /// A remedy plan as the common screens show it: the nested expert lists (dosha
    /// families, exact hora/tithi windows) are dropped, since their `name` and `words`
    /// fields share names with plain fields elsewhere.
    fn parihara_shown(mut p: PariharaRecord) -> PariharaRecord {
        p.doshas.clear();
        for r in p.remedies.iter_mut() {
            r.windows.clear();
        }
        p
    }

    /// `(field, value)` for every string in a Debug rendering.
    fn strings(debug: &str) -> Vec<(String, String)> {
        let b = debug.as_bytes();
        let mut out = Vec::new();
        let mut field = String::new();
        let mut i = 0;
        while i < b.len() {
            let c = b[i];
            if c == b'"' {
                // Debug escapes some characters (Malayalam vowel signs among them) as
                // \u{..}; decode them so the text is read as the person reads it.
                let mut j = i + 1;
                let mut s: Vec<u8> = Vec::new();
                while j < b.len() && b[j] != b'"' {
                    if b[j] == b'\\' && j + 1 < b.len() {
                        j += 1;
                        match b[j] {
                            b'u' if j + 1 < b.len() && b[j + 1] == b'{' => {
                                let end = debug[j..].find('}').map(|k| j + k).unwrap_or(j);
                                if let Some(ch) = u32::from_str_radix(&debug[j + 2..end], 16).ok().and_then(char::from_u32) {
                                    let mut buf = [0u8; 4];
                                    s.extend_from_slice(ch.encode_utf8(&mut buf).as_bytes());
                                }
                                j = end + 1;
                                continue;
                            }
                            b'n' => s.push(b'\n'),
                            b't' => s.push(b'\t'),
                            other => s.push(other),
                        }
                        j += 1;
                        continue;
                    }
                    s.push(b[j]);
                    j += 1;
                }
                out.push((field.clone(), String::from_utf8_lossy(&s).into_owned()));
                i = j + 1;
                continue;
            }
            if c.is_ascii_alphabetic() || c == b'_' {
                let start = i;
                while i < b.len() && (b[i].is_ascii_alphanumeric() || b[i] == b'_') {
                    i += 1;
                }
                if i + 1 < b.len() && b[i] == b':' && b[i + 1] == b' ' {
                    field = debug[start..i].to_string();
                }
                continue;
            }
            i += 1;
        }
        out
    }

    fn audit(what: &str, debug: String, hits: &mut Vec<String>) {
        audit_in(kshana_rules::Lang::En, what, debug, hits)
    }

    /// Fields that hold a sentence and must never be empty.
    const SENTENCE: &[&str] = &["headline", "what_it_does", "intro", "why", "how"];

    /// Words after which "a" is right even before a vowel letter.
    fn takes_a(next: &str) -> bool {
        let n = next.to_ascii_lowercase();
        n.starts_with("one") || n.starts_with("once") || n.starts_with("use") || n.starts_with("usu") || n.starts_with("uni") || n.starts_with("eu") || n.starts_with("ur")
    }

    /// A style slip in an English sentence: grammar a reader would notice.
    fn style(v: &str) -> Option<&'static str> {
        for (bad, why) in [("Children asks", "children asks"), ("Children is ", "children is"), ("Children has ", "children has"), (" ,", "space before comma"), (" .", "space before full stop"), (" ;", "space before semicolon"), ("..", "double full stop"), ("  ", "double space")] {
            if v.contains(bad) {
                return Some(why);
            }
        }
        let words: Vec<&str> = v.split(|c: char| c.is_whitespace()).filter(|w| !w.is_empty()).collect();
        for w in words.windows(2) {
            let (a, b) = (w[0], w[1].trim_start_matches(|c: char| !c.is_alphanumeric()));
            if (a == "a" || a == "A") && !b.is_empty() {
                let first = b.chars().next().unwrap_or('x').to_ascii_lowercase();
                let vowel = "aeiou".contains(first) && !takes_a(b);
                let silent_h = ["hour", "honest", "heir", "honour"].iter().any(|h| b.to_ascii_lowercase().starts_with(h));
                if vowel || silent_h {
                    return Some("a before a vowel sound");
                }
            }
            let clean = |s: &str| s.trim_matches(|c: char| !c.is_alphanumeric()).to_ascii_lowercase();
            if !clean(w[0]).is_empty() && clean(w[0]) == clean(w[1]) && clean(w[0]).chars().all(|c| c.is_alphabetic()) && w[0].chars().last().map_or(true, |c| c.is_alphanumeric()) {
                return Some("doubled word");
            }
        }
        let b = v.as_bytes();
        for i in 0..b.len().saturating_sub(2) {
            if b[i] == b'.' && b[i + 1] == b' ' && b[i + 2].is_ascii_lowercase() {
                return Some("lower case after a full stop");
            }
        }
        None
    }

    fn audit_in(lang: kshana_rules::Lang, what: &str, debug: String, hits: &mut Vec<String>) {
        for (f, v) in strings(&debug) {
            if NOT_SHOWN.contains(&f.as_str()) {
                continue;
            }
            if let Some(w) = kshana_rules::plain::jargon_in(lang, &v) {
                hits.push(format!("{what}.{f} [{w}]: {v}"));
            }
            if SENTENCE.contains(&f.as_str()) && v.trim().is_empty() {
                hits.push(format!("{what}.{f} [empty sentence]"));
            }
            let s = if lang == kshana_rules::Lang::En {
                style(&v)
            } else {
                [(" ,", "space before comma"), ("  ", "double space"), ("..", "double full stop")].iter().find(|(b, _)| v.contains(b)).map(|x| x.1)
            };
            if let Some(why) = s {
                hits.push(format!("{what}.{f} [style: {why}]: {v}"));
            }
        }
    }

    #[test]
    fn the_style_check_catches_slips() {
        assert_eq!(style("Children asks for care."), Some("children asks"));
        assert_eq!(style("It is a unlucky stretch."), Some("a before a vowel sound"));
        assert_eq!(style("Wait for a hour."), Some("a before a vowel sound"));
        assert_eq!(style("A one-time gift, a useful habit."), None);
        assert_eq!(style("the the day"), Some("doubled word"));
        assert_eq!(style("Done. then more"), Some("lower case after a full stop"));
        assert_eq!(style("Fine sentence, with care."), None);
    }

    fn at(y: i64, mo: u32, d: u32, h: u32) -> ExactInstant {
        instant_from_utc(UtcFields { year: y, month: mo, day: d, hour: h, minute: 0, second: 0, nanos: 0 }).unwrap()
    }

    #[test]
    fn nothing_the_person_reads_names_the_astrology() {
        let p = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../data/de421.bsp");
        let engine = Engine::open(p.to_string_lossy().into_owned(), None).expect("the kernel is needed for this test");
        let people = [
            (at(1990, 2, 20, 5), 9.9312, 76.2673),
            (at(1997, 9, 22, 13), 9.9312, 76.2673),
            (at(1975, 6, 3, 23), 28.6139, 77.2090),
        ];
        let instants = [at(2026, 10, 17, 5), at(2027, 3, 5, 12), at(2031, 6, 20, 2)];
        let (hs, ay) = (HouseSystem::Placidus, AyanamsaChoice::Lahiri);
        let mut hits = Vec::new();
        let full = std::env::var("KSHANA_AUDIT_FULL").is_ok();
        for (pi, &(b, la, lo)) in people.iter().enumerate() {
            let (ob, ola, olo) = people[(pi + 1) % people.len()];
            for (ti, &t) in instants.iter().enumerate() {
                let tag = |s: &str| format!("p{pi}t{ti}.{s}");
                audit(&tag("moment"), format!("{:?}", engine.forecast_moment(b, la, lo, la, lo, hs, ay, t, "en".into()).unwrap()), &mut hits);
                audit(&tag("briefing"), format!("{:?}", engine.briefing(b, la, lo, la, lo, hs, ay, vec!["Love".into(), "Career".into(), "Money".into(), "Health".into()], t, "en".into()).unwrap()), &mut hits);
                audit(&tag("letter"), format!("{:?}", engine.letter(b, la, lo, la, lo, hs, ay, t, vec![]).unwrap()), &mut hits);
                for s in ["day", "week", "month", "year"] {
                    audit(&tag(&format!("outlook_{s}")), format!("{:?}", engine.outlook(b, la, lo, la, lo, hs, ay, s.into(), t, "en".into(), vec![]).unwrap()), &mut hits);
                }
                audit(&tag("countdowns"), format!("{:?}", engine.countdowns(b, la, lo, la, lo, hs, ay, t).unwrap()), &mut hits);
                audit(&tag("festivals"), format!("{:?}", engine.festivals(b, la, lo, hs, ay, t, 35).unwrap()), &mut hits);
                audit(&tag("year"), format!("{:?}", engine.year_chapter(b, la, lo, la, lo, hs, ay, t).unwrap()), &mut hits);
                audit(&tag("parihara"), format!("{:?}", parihara_shown(engine.parihara(b, la, lo, ay, t, None).unwrap())), &mut hits);
                for life in life_names() {
                    if ti == 0 || full {
                        audit(&tag(&format!("explain_{life}")), format!("{:?}", engine.explain(b, la, lo, la, lo, hs, ay, life.clone(), t).unwrap()), &mut hits);
                        audit(&tag(&format!("parihara_{life}")), format!("{:?}", parihara_shown(engine.parihara(b, la, lo, ay, t, Some(life.clone())).unwrap())), &mut hits);
                    }
                    for q in questions() {
                        if ti == 0 || full {
                            if let Ok(a) = engine.ask(b, la, lo, la, lo, hs, ay, life.clone(), q.key.clone(), t) {
                                audit(&tag(&format!("ask_{life}_{}", q.key)), format!("{a:?}"), &mut hits);
                            }
                        }
                    }
                }
                if ti == 0 {
                    for tp in topics().iter().take(if full { 200 } else { 12 }) {
                        if let Ok(a) = engine.ask_topic(b, la, lo, la, lo, hs, ay, tp.key.clone(), "when".into(), t) {
                            audit(&tag(&format!("topic_{}", tp.key)), format!("{a:?}"), &mut hits);
                        }
                    }
                    for pu in purposes() {
                        audit(&tag(&format!("appointment_{}", pu.key)), format!("{:?}", engine.appointment(b, la, lo, la, lo, hs, ay, pu.key.clone(), t).unwrap()), &mut hits);
                        audit(&tag(&format!("slots_{}", pu.key)), format!("{:?}", engine.best_slots(b, la, lo, la, lo, hs, ay, pu.key.clone(), t, 7, 5).unwrap()), &mut hits);
                    }
                    audit(&tag("timeline"), format!("{:?}", engine.timeline(b, la, lo, hs, ay, t).unwrap()), &mut hits);
                    audit(&tag("chart_yogas"), format!("{:?}", engine.chart_yogas(b, la, lo, ay, t).unwrap()), &mut hits);
                    audit(&tag("kundali"), format!("{:?}", engine.kundali(b, la, lo, ob, ola, olo, hs, ay, true).unwrap()), &mut hits);
                    audit(&tag("talk"), format!("{:?}", engine.talk_window(b, la, lo, ob, ola, olo, la, lo, hs, ay, t, 14).unwrap()), &mut hits);
                    for life in std::iter::once(None).chain(life_names().into_iter().map(Some)) {
                        audit(&tag(&format!("tree_{life:?}")), format!("{:?}", engine.remedy_tree(b, la, lo, la, lo, hs, ay, life.clone(), t, "en".into(), vec![]).unwrap()), &mut hits);
                    }
                    audit(&tag("past"), format!("{:?}", engine.past_checks(b, la, lo, hs, ay, t, "en".into(), vec![]).unwrap()), &mut hits);
                    let group = vec![PersonInput { birth: b, lat: la, lon: lo }, PersonInput { birth: ob, lat: ola, lon: olo }];
                    audit(&tag("together"), format!("{:?}", engine.best_slots_together(group.clone(), la, lo, hs, ay, "family".into(), t, 7, 5, "en".into()).unwrap()), &mut hits);
                    for code in ["ml", "hi"] {
                        let lang = kshana_rules::Lang::parse(code);
                        let tg = |s: &str| format!("p{pi}t{ti}.{code}.{s}");
                        audit_in(lang, &tg("moment"), format!("{:?}", engine.forecast_moment(b, la, lo, la, lo, hs, ay, t, code.into()).unwrap()), &mut hits);
                        let br = engine.briefing(b, la, lo, la, lo, hs, ay, vec!["Love".into(), "Career".into()], t, code.into()).unwrap();
                        audit_in(lang, &tg("briefing.season"), format!("{:?}", (&br.paragraphs[0], &br.saturn_words, &br.moment.title, &br.moment.day_title)), &mut hits);
                        for s in ["day", "week", "month", "year"] {
                            audit_in(lang, &tg(&format!("outlook_{s}")), format!("{:?}", engine.outlook(b, la, lo, la, lo, hs, ay, s.into(), t, code.into(), vec![]).unwrap()), &mut hits);
                        }
                        audit_in(lang, &tg("tree"), format!("{:?}", engine.remedy_tree(b, la, lo, la, lo, hs, ay, None, t, code.into(), vec![]).unwrap()), &mut hits);
                        audit_in(lang, &tg("tree_love"), format!("{:?}", engine.remedy_tree(b, la, lo, la, lo, hs, ay, Some("Love".into()), t, code.into(), vec![]).unwrap()), &mut hits);
                        audit_in(lang, &tg("past"), format!("{:?}", engine.past_checks(b, la, lo, hs, ay, t, code.into(), vec![]).unwrap()), &mut hits);
                        audit_in(lang, &tg("together"), format!("{:?}", engine.best_slots_together(group.clone(), la, lo, hs, ay, "family".into(), t, 7, 3, code.into()).unwrap()), &mut hits);
                    }
                }
                audit(&tag("couple"), format!("{:?}", engine.couple(b, la, lo, ob, ola, olo, la, lo, hs, ay, true, t).unwrap()), &mut hits);
                for q in questions() {
                    if let Ok(a) = engine.couple_ask(b, la, lo, ob, ola, olo, la, lo, hs, ay, q.key.clone(), t) {
                        audit(&tag(&format!("couple_ask_{}", q.key)), format!("{a:?}"), &mut hits);
                    }
                }
            }
        }
        audit("questions", format!("{:?}", questions()), &mut hits);
        audit("purposes", format!("{:?}", purposes()), &mut hits);
        audit("topics", format!("{:?}", topics()), &mut hits);
        audit("hora_lore", format!("{:?}", hora_lore_all()), &mut hits);
        let rec = engine.rectify(9.9312, 76.2673, HouseSystem::Placidus, AyanamsaChoice::Lahiri, at(1990, 2, 20, 4), at(1990, 2, 20, 6), vec![LifeEventRecord { at: at(2015, 5, 10, 6), life: "Love".into(), good: true }], 3);
        audit("rectify", format!("{rec:?}"), &mut hits);
        hits.sort();
        hits.dedup();
        if !hits.is_empty() {
            let path = std::env::temp_dir().join("kshana_plain_audit.txt");
            let _ = std::fs::write(&path, hits.join("\n"));
            panic!("{} sentences name the astrology (all in {}); first 40:\n{}", hits.len(), path.display(), hits.iter().take(40).cloned().collect::<Vec<_>>().join("\n"));
        }
    }
}

