/// Put a moment's own words into the reader's language: the moment and day titles, the
/// day's quality, the long test's name, the windows and the hour.
fn localise_moment(rec: &mut MomentRecord, m: &kshana_rules::Moment, lang: kshana_rules::Lang, lon: f64) {
    use kshana_rules::lang as l;
    rec.title = l::moment_title(lang, m.tara, m.hora.as_ref().map(|h| h.lord));
    rec.day_title = l::day_title(lang, m.tara, kshana_rules::prashna::day_lord(m.at, lon));
    rec.tara_words = l::day_quality(lang, m.tara).to_string();
    rec.saturn_words = l::long_test(lang, m.saturn).to_string();
    for w in rec.windows.iter_mut() {
        w.label = l::window_label(lang, &w.label);
    }
    if let (Some(h), Some(hr)) = (m.hora.as_ref(), rec.hora.as_mut()) {
        hr.words = l::hour_nature(lang, h.lord).to_string();
    }
}

/// How sure an answer is, in words, in the reader's language; `confidence` is 0–100.
#[uniffi::export]
pub fn sure_words(lang: String, confidence: f64) -> String {
    kshana_rules::lang::sure_words(kshana_rules::Lang::parse(&lang), confidence).to_string()
}

/// One remedy in a branch of the tree.
#[derive(Clone, Debug, uniffi::Record)]
pub struct TreeRemedyRecord {
    /// What to do.
    pub title: String,
    /// What it eases, in life terms.
    pub why: String,
    /// Concrete steps.
    pub how: String,
    /// The day ("Saturday", "any day"), in the reader's language.
    pub day: String,
    /// How much it asks ("once a week").
    pub effort: String,
    /// The branch key.
    pub kind: String,
    /// A chant's text in the reader's script, for chant remedies.
    pub mantra: Option<String>,
}

/// One branch of remedies.
#[derive(Clone, Debug, uniffi::Record)]
pub struct BranchRecord {
    /// `deeds`, `giving`, `habits`, `nature`, `mind`, `prayer`, `tradition`.
    pub key: String,
    /// Title.
    pub title: String,
    /// What the branch is.
    pub intro: String,
    /// The remedies.
    pub items: Vec<TreeRemedyRecord>,
}

/// One cause in the tree: a pressure, what it does, when it eases, and its remedies.
#[derive(Clone, Debug, uniffi::Record)]
pub struct CauseNodeRecord {
    /// The engine's key for the influence (expert only; never shown).
    pub key: String,
    /// `dasha`, `gochara` or `natal` (expert only).
    pub source: String,
    /// The pressure in plain words.
    pub title: String,
    /// What it does in the person's life.
    pub what_it_does: String,
    /// When it began, when known.
    pub since: Option<ExactInstant>,
    /// When it eases, when known.
    pub until: Option<ExactInstant>,
    /// The end in words.
    pub until_words: String,
    /// Weight on the life, in points (0–50).
    pub strength: f64,
    /// "Pressing hard" and so on.
    pub strength_words: String,
    /// The seven branches.
    pub branches: Vec<BranchRecord>,
    /// The chart reason, shown only when the person taps "How this helps".
    pub how_it_helps: String,
}

/// The remedy tree for a life.
#[derive(Clone, Debug, uniffi::Record)]
pub struct RemedyTreeRecord {
    /// The life's key ("Love").
    pub life: String,
    /// What is wrong and roughly until when.
    pub headline: String,
    /// The causes, strongest first.
    pub causes: Vec<CauseNodeRecord>,
}

/// One question about the person's past.
#[derive(Clone, Debug, uniffi::Record)]
pub struct PastCheckRecord {
    /// First day of the stretch.
    pub from: ExactInstant,
    /// Last day of the stretch.
    pub to: ExactInstant,
    /// The life's key ("Love").
    pub life: String,
    /// The yes-or-no question, in the reader's language.
    pub question: String,
    /// The same stretch said as a plain statement.
    pub statement: String,
    /// True for a good stretch.
    pub good: bool,
    /// How far it stood from the life's average, in points.
    pub strength: f64,
}

/// One answered stretch of the past, for sharpening the birth time.
#[derive(Clone, Debug, uniffi::Record)]
pub struct PastAnswerInput {
    /// First day of the stretch.
    pub from: ExactInstant,
    /// Last day of the stretch.
    pub to: ExactInstant,
    /// The life's key ("Love").
    pub life: String,
    /// True if the stretch was said to be good.
    pub good: bool,
    /// "yes", "close" or "no".
    pub verdict: String,
}

/// One candidate birth time, scored against the answers.
#[derive(Clone, Debug, uniffi::Record)]
pub struct BirthFitRecord {
    /// The candidate birth instant.
    pub birth: ExactInstant,
    /// Minutes from the recorded time (positive = later).
    pub shift_min: f64,
    /// Share of the belief on this time, 0..1.
    pub prob: f64,
    /// How many answers this time explains.
    pub explained: u32,
    /// Rising sign, 0 = Aries (for the expert view only).
    pub lagna_sign: u8,
    /// Moon's star, 0 = Ashwini (for the expert view only).
    pub moon_star: u32,
    /// Each technique's own log-likelihood of the answers against chance, nats, in the
    /// order of `BirthRefineRecord::witness_keys` (for the expert view only).
    pub by_witness: Vec<f64>,
}

/// What the answers say about the birth time.
#[derive(Clone, Debug, uniffi::Record)]
pub struct BirthRefineRecord {
    /// The best few candidates, best first.
    pub fits: Vec<BirthFitRecord>,
    /// The time to suggest, if the answers clearly prefer it over the recorded one.
    pub suggested: Option<BirthFitRecord>,
    /// Share of the belief within five minutes of the best time: how settled it is.
    pub settled: f64,
    /// How many answers the recorded time explains.
    pub recorded_explains: u32,
    /// log10 of the evidence that the answers say anything about the birth time at all,
    /// against answers given at random; a shift is suggested only from 1.3 (20 to 1).
    pub log10_bayes: f64,
    /// The moments in the window where the chart changes, in time order.
    pub boundaries: Vec<learn::BirthBoundaryRecord>,
    /// The boundary before the best time (or the window's start): with `bracket_to`, the
    /// stretch of birth times where everything the boundaries mark holds.
    pub bracket_from: Option<ExactInstant>,
    /// The boundary after the best time (or the window's end).
    pub bracket_to: Option<ExactInstant>,
    /// Finest-division (D60) changes inside the bracket: a flag only, never scored.
    pub d60_in_bracket: u32,
    /// Keys of `BirthFitRecord::by_witness` (for the expert view only).
    pub witness_keys: Vec<String>,
}

/// A person for a group reading.
#[derive(Clone, Debug, uniffi::Record)]
pub struct PersonInput {
    /// Birth instant.
    pub birth: ExactInstant,
    /// Birth latitude.
    pub lat: f64,
    /// Birth longitude.
    pub lon: f64,
}

/// An hour that suits several people at once.
#[derive(Clone, Debug, uniffi::Record)]
pub struct GroupSlotRecord {
    /// Start.
    pub start: ExactInstant,
    /// End.
    pub end: ExactInstant,
    /// Combined, 0–100, weighted to the weakest person.
    pub score: f64,
    /// Each person's score, 0–100, in the order given.
    pub each: Vec<f64>,
    /// Index of the person it suits best.
    pub best_for: u32,
    /// Index of the person it suits least.
    pub weakest_for: u32,
    /// In plain words, in the reader's language.
    pub words: String,
}

#[uniffi::export]
impl Engine {
    /// The remedy tree for `life` (a key from `life_names()`, or none for the weakest
    /// life now): the causes in plain words and seven branches of remedies each, deeds
    /// anyone can do first and the Hindu tradition last and optional.
    #[allow(clippy::too_many_arguments)]
    pub fn remedy_tree(
        &self,
        birth: ExactInstant,
        birth_lat: f64,
        birth_lon: f64,
        lat: f64,
        lon: f64,
        system: HouseSystem,
        ayanamsa: AyanamsaChoice,
        life: Option<String>,
        at: ExactInstant,
        lang: String,
        focus: Vec<String>,
    ) -> Result<RemedyTreeRecord, KshanaError> {
        let natal = self.natal(birth, birth_lat, birth_lon, system, ayanamsa)?;
        let obs = Observer { latitude_deg: lat, longitude_deg: lon, height_m: 0.0 };
        let life = life.as_deref().and_then(kshana_rules::Life::parse);
        let t = kshana_rules::remedy_tree(&self.spk, self.eop.as_ref(), &natal, &obs, to_house_system(system), ayanamsa.into(), life, kshana_rules::Lang::parse(&lang), at.into(), &focus_of(&focus))
            .map_err(|e| KshanaError::Engine(format!("{e:?}")))?;
        Ok(RemedyTreeRecord {
            life: t.life.name().to_string(),
            headline: t.headline,
            causes: t
                .causes
                .into_iter()
                .map(|c| CauseNodeRecord {
                    how_it_helps: c.how_it_helps.clone(),
                    key: lord_name(c.key),
                    source: c.source.to_string(),
                    title: c.title,
                    what_it_does: c.what_it_does,
                    since: c.since.map(Into::into),
                    until: c.until.map(Into::into),
                    until_words: c.until_words,
                    strength: c.strength,
                    strength_words: c.strength_words,
                    branches: c
                        .branches
                        .into_iter()
                        .map(|b| BranchRecord {
                            key: b.key.to_string(),
                            title: b.title,
                            intro: b.intro,
                            items: b
                                .items
                                .into_iter()
                                .map(|r| TreeRemedyRecord { title: r.title, why: r.why, how: r.how, day: r.day, effort: r.effort, kind: r.kind.to_string(), mantra: r.mantra })
                                .collect(),
                        })
                        .collect(),
                })
                .collect(),
        })
    }

    /// Three to five yes-or-no questions about real stretches of the person's last six
    /// years, the strongest dips and peaks the reading marks, for the first minute of the
    /// app: the past checked before the future is told.
    #[allow(clippy::too_many_arguments)]
    pub fn past_checks(
        &self,
        birth: ExactInstant,
        birth_lat: f64,
        birth_lon: f64,
        system: HouseSystem,
        ayanamsa: AyanamsaChoice,
        at: ExactInstant,
        lang: String,
        focus: Vec<String>,
    ) -> Result<Vec<PastCheckRecord>, KshanaError> {
        let natal = self.natal(birth, birth_lat, birth_lon, system, ayanamsa)?;
        let obs = Observer { latitude_deg: birth_lat, longitude_deg: birth_lon, height_m: 0.0 };
        let c = kshana_rules::past_checks(&self.spk, self.eop.as_ref(), &natal, &obs, ayanamsa.into(), kshana_rules::Lang::parse(&lang), at.into(), &focus_of(&focus))
            .map_err(|e| KshanaError::Engine(format!("{e:?}")))?;
        Ok(c
            .into_iter()
            .map(|x| PastCheckRecord { from: x.from.into(), to: x.to.into(), life: x.life.name().to_string(), question: x.question, statement: x.statement, good: x.good, strength: x.strength })
            .collect())
    }

    /// The past, told first: the strongest dated stretches from the person's early teens
    /// to now, skipping those already asked (`asked_from`/`asked_to` pairs).
    /// `window_min` is how far the birth time may be off, in minutes. `sharpen` picks the
    /// stretches that best split nearby birth times ("ask me more"); otherwise the
    /// safest, the ones every nearby time agrees on.
    #[allow(clippy::too_many_arguments)]
    pub fn past_reveal(
        &self,
        birth: ExactInstant,
        birth_lat: f64,
        birth_lon: f64,
        system: HouseSystem,
        ayanamsa: AyanamsaChoice,
        at: ExactInstant,
        lang: String,
        window_min: f64,
        asked_from: Vec<ExactInstant>,
        asked_to: Vec<ExactInstant>,
        count: u32,
        sharpen: bool,
    ) -> Result<Vec<PastCheckRecord>, KshanaError> {
        let natal = self.natal(birth, birth_lat, birth_lon, system, ayanamsa)?;
        let obs = Observer { latitude_deg: birth_lat, longitude_deg: birth_lon, height_m: 0.0 };
        let asked: Vec<(kshana_time::Instant, kshana_time::Instant)> = asked_from.iter().zip(&asked_to).map(|(a, b)| ((*a).into(), (*b).into())).collect();
        let c = kshana_rules::past_reveal(
            &self.spk,
            self.eop.as_ref(),
            &natal,
            &obs,
            to_house_system(system),
            ayanamsa.into(),
            kshana_rules::Lang::parse(&lang),
            at.into(),
            window_min,
            &asked,
            count as usize,
            sharpen,
        )
        .map_err(|e| KshanaError::Engine(format!("{e:?}")))?;
        Ok(c.into_iter().map(past_check_record).collect())
    }

    /// Every birth time within ±`window_min` minutes, scored against the person's
    /// answers about their past. A No counts as much as a Yes: a wrong guess still
    /// helps, because it narrows down the birth time.
    #[allow(clippy::too_many_arguments)]
    pub fn refine_birth_time(
        &self,
        birth: ExactInstant,
        birth_lat: f64,
        birth_lon: f64,
        system: HouseSystem,
        ayanamsa: AyanamsaChoice,
        window_min: f64,
        answers: Vec<PastAnswerInput>,
    ) -> BirthRefineRecord {
        let obs = Observer { latitude_deg: birth_lat, longitude_deg: birth_lon, height_m: 0.0 };
        let ans = learn::answers_of(&answers);
        let r = kshana_rules::refine_birth_detail(&self.spk, self.eop.as_ref(), &obs, to_house_system(system), ayanamsa.into(), birth.into(), window_min, 2.0, &ans, true);
        let fits = &r.fits;
        let rec = |f: &kshana_rules::BirthFit| BirthFitRecord {
            birth: f.birth.into(),
            shift_min: f.shift_min,
            prob: f.prob,
            explained: f.explained as u32,
            lagna_sign: f.lagna_sign,
            moon_star: f.moon_star as u32,
            by_witness: f.by_witness.to_vec(),
        };
        let settled = fits.first().map(|b| fits.iter().filter(|f| (f.shift_min - b.shift_min).abs() <= 5.0).map(|f| f.prob).sum()).unwrap_or(0.0);
        let recorded_explains = fits.iter().find(|f| f.shift_min.abs() < 1e-9).map(|f| f.explained as u32).unwrap_or(0);
        BirthRefineRecord {
            suggested: r.suggested(ans.len()).as_ref().map(rec),
            fits: fits.iter().take(7).map(rec).collect(),
            settled,
            recorded_explains,
            log10_bayes: r.log10_bayes,
            boundaries: r.boundaries.iter().map(learn::boundary_record).collect(),
            bracket_from: r.bracket.map(|b| b.0.into()),
            bracket_to: r.bracket.map(|b| b.1.into()),
            d60_in_bracket: r.d60_in_bracket as u32,
            witness_keys: kshana_rules::witness::WITNESSES.iter().map(|w| w.key().to_string()).collect(),
        }
    }

    /// One stretch of the coming weeks, to be sealed now and opened when it has passed;
    /// a good one when there is one. None when nothing stands out enough to seal.
    #[allow(clippy::too_many_arguments)]
    pub fn seal_pick(
        &self,
        birth: ExactInstant,
        birth_lat: f64,
        birth_lon: f64,
        system: HouseSystem,
        ayanamsa: AyanamsaChoice,
        at: ExactInstant,
        lang: String,
    ) -> Result<Option<PastCheckRecord>, KshanaError> {
        let natal = self.natal(birth, birth_lat, birth_lon, system, ayanamsa)?;
        let obs = Observer { latitude_deg: birth_lat, longitude_deg: birth_lon, height_m: 0.0 };
        let s = kshana_rules::seal_pick(&self.spk, self.eop.as_ref(), &natal, &obs, ayanamsa.into(), kshana_rules::Lang::parse(&lang), at.into())
            .map_err(|e| KshanaError::Engine(format!("{e:?}")))?;
        Ok(s.map(past_check_record))
    }

    /// The best `limit` hours in the next `days` for `purpose` (a key from `purposes()`)
    /// for everyone in `people` at once, read where they will be (`lat`/`lon`).
    #[allow(clippy::too_many_arguments)]
    pub fn best_slots_together(
        &self,
        people: Vec<PersonInput>,
        lat: f64,
        lon: f64,
        system: HouseSystem,
        ayanamsa: AyanamsaChoice,
        purpose: String,
        from: ExactInstant,
        days: u32,
        limit: u32,
        lang: String,
    ) -> Result<Vec<GroupSlotRecord>, KshanaError> {
        let purpose = kshana_rules::Purpose::parse(&purpose).ok_or_else(|| KshanaError::Engine(format!("unknown purpose {purpose}")))?;
        let mut natals = Vec::with_capacity(people.len());
        for p in &people {
            natals.push(self.natal(p.birth, p.lat, p.lon, system, ayanamsa)?);
        }
        let obs = Observer { latitude_deg: lat, longitude_deg: lon, height_m: 0.0 };
        let s = kshana_rules::best_slots_together(
            &self.spk,
            self.eop.as_ref(),
            &natals,
            &obs,
            to_house_system(system),
            ayanamsa.into(),
            purpose,
            from.into(),
            days as usize,
            limit as usize,
            kshana_rules::Lang::parse(&lang),
        )
        .map_err(|e| KshanaError::Engine(format!("{e:?}")))?;
        Ok(s
            .into_iter()
            .map(|g| GroupSlotRecord {
                start: g.start.into(),
                end: g.end.into(),
                score: g.score * 100.0,
                each: g.each.iter().map(|v| v * 100.0).collect(),
                best_for: g.best_for as u32,
                weakest_for: g.weakest_for as u32,
                words: g.words,
            })
            .collect())
    }
}

/// Every choice the app offers must change what the person reads: each span of Ahead,
/// each question under a life, each matter, each purpose, each life's remedy tree and
/// explanation, each couple question. Two different choices that give the same words
/// are a data-placement bug.
#[cfg(test)]
mod distinct {
    use super::*;
    use std::collections::HashMap;

    fn at(y: i64, mo: u32, d: u32, h: u32) -> ExactInstant {
        instant_from_utc(UtcFields { year: y, month: mo, day: d, hour: h, minute: 0, second: 0, nanos: 0 }).unwrap()
    }

    /// Fails with every group of keys that share the same text.
    fn all_differ(what: &str, items: Vec<(String, String)>, problems: &mut Vec<String>) {
        let mut by: HashMap<String, Vec<String>> = HashMap::new();
        for (k, v) in items {
            by.entry(v).or_default().push(k);
        }
        for (v, ks) in by {
            if ks.len() > 1 {
                problems.push(format!("{what}: {ks:?} all read: {v}"));
            }
        }
    }

    #[test]
    fn every_choice_changes_what_the_person_reads() {
        let p = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../data/de421.bsp");
        let engine = Engine::open(p.to_string_lossy().into_owned(), None).expect("kernel");
        let (b, la, lo) = (at(1990, 2, 20, 5), 9.9312, 76.2673);
        let (ob, ola, olo) = (at(1997, 9, 22, 13), 9.9312, 76.2673);
        let t = at(2026, 10, 18, 10);
        let (hs, ay) = (HouseSystem::Placidus, AyanamsaChoice::Lahiri);
        let mut problems = Vec::new();

        // Ahead: the four spans, each as a whole and each life within it.
        let spans: Vec<(String, OutlookRecord)> = ["day", "week", "month", "year"]
            .iter()
            .map(|s| (s.to_string(), engine.outlook(b, la, lo, la, lo, hs, ay, s.to_string(), t, "en".into(), vec![]).unwrap()))
            .collect();
        all_differ("outlook headline", spans.iter().map(|(k, o)| (k.clone(), o.headline.clone())).collect(), &mut problems);
        all_differ("outlook season", spans.iter().map(|(k, o)| (k.clone(), o.season.clone())).collect(), &mut problems);
        for life in life_names() {
            all_differ(
                &format!("outlook {life}"),
                spans.iter().map(|(k, o)| (k.clone(), o.lives.iter().find(|l| l.life == life).map(|l| l.words.clone()).unwrap_or_default())).collect(),
                &mut problems,
            );
        }
        // The same life on every span must not land on one best date everywhere.
        let mut best_dates: HashMap<String, usize> = HashMap::new();
        for (_, o) in &spans {
            for l in &o.lives {
                if let Some(a) = &l.best_at {
                    let unit = if o.span == "day" { 3_600 } else { 86_400 };
                    *best_dates.entry(format!("{}|{}", o.span, a.tai_seconds / unit)).or_default() += 1;
                }
            }
        }
        for (k, n) in &best_dates {
            if *n == 9 {
                problems.push(format!("outlook {k}: all nine lives share one best date"));
            }
        }

        // Ask: each question under a life.
        for life in life_names() {
            let answers: Vec<(String, String)> = questions()
                .iter()
                .filter_map(|q| engine.ask(b, la, lo, la, lo, hs, ay, life.clone(), q.key.clone(), t).ok().map(|a| (q.key.clone(), a.headline)))
                .collect();
            all_differ(&format!("ask {life}"), answers, &mut problems);
        }
        // Ask: each matter under a life, same question.
        for life in life_names() {
            let answers: Vec<(String, String)> = topics()
                .iter()
                .filter(|tp| tp.life == life)
                .filter_map(|tp| engine.ask_topic(b, la, lo, la, lo, hs, ay, tp.key.clone(), "will_it_happen".into(), t).ok().map(|a| (tp.key.clone(), format!("{} {}", a.headline, a.when_words))))
                .collect();
            all_differ(&format!("matters under {life}"), answers, &mut problems);
        }
        // Plan: each purpose at the same hour.
        let plans: Vec<(String, String)> = purposes()
            .iter()
            .map(|pu| {
                let a = engine.appointment(b, la, lo, la, lo, hs, ay, pu.key.clone(), t).unwrap();
                (pu.key.clone(), format!("{} {}", a.headline, a.advice.join(" ")))
            })
            .collect();
        all_differ("plan purposes", plans, &mut problems);
        // Life pages: the explanation of each life.
        let explains: Vec<(String, String)> = life_names()
            .into_iter()
            .map(|l| {
                let e = engine.explain(b, la, lo, la, lo, hs, ay, l.clone(), t).unwrap();
                (l, e.headline)
            })
            .collect();
        all_differ("explain per life", explains, &mut problems);
        // Remedies: each life's tree.
        let trees: Vec<(String, String)> = life_names()
            .into_iter()
            .map(|l| {
                let r = engine.remedy_tree(b, la, lo, la, lo, hs, ay, Some(l.clone()), t, "en".into(), vec![]).unwrap();
                (l, format!("{} | {}", r.headline, r.causes.iter().map(|c| c.title.clone()).collect::<Vec<_>>().join(" / ")))
            })
            .collect();
        all_differ("remedy tree per life", trees, &mut problems);
        // Us: each question about the two of you.
        let couple: Vec<(String, String)> = questions()
            .iter()
            .filter_map(|q| engine.couple_ask(b, la, lo, ob, ola, olo, la, lo, hs, ay, q.key.clone(), t).ok().map(|a| (q.key.clone(), a.headline)))
            .collect();
        all_differ("couple questions", couple, &mut problems);
        // First check: different lives, different stretches.
        let pc = engine.past_checks(b, la, lo, hs, ay, t, "en".into(), vec![]).unwrap();
        all_differ("past checks", pc.iter().map(|c| (c.life.clone(), c.question.clone())).collect(), &mut problems);
        let lives: std::collections::HashSet<_> = pc.iter().map(|c| c.life.clone()).collect();
        if lives.len() != pc.len() {
            problems.push("past checks repeat a life".into());
        }

        if !problems.is_empty() {
            panic!("{} places show the same words for different choices:\n{}", problems.len(), problems.join("\n"));
        }
    }
}

/// The parts of life the person chose, by name; empty means all of them.
fn focus_of(v: &[String]) -> Vec<kshana_rules::Life> {
    v.iter().filter_map(|s| kshana_rules::Life::parse(s)).collect()
}

/// One thing that is coming.
#[derive(Clone, Debug, uniffi::Record)]
#[allow(missing_docs)]
pub struct FutureEventRecord {
    pub from: ExactInstant,
    pub to: ExactInstant,
    /// The life it is about, or none for a turn that touches the whole of life.
    pub life: Option<String>,
    /// `opening`, `pressure`, `chapter`, `test_begins`, `test_pause`, `test_returns`, `test_ends`.
    pub kind: String,
    pub headline: String,
    pub detail: String,
    /// 0–100.
    pub strength: f64,
    pub peak: Option<ExactInstant>,
}

#[uniffi::export]
impl Engine {
    /// What is coming in the `months` from `at`, for the chosen lives, in order: the
    /// windows that open and the stretches that press, the turns of the long chapters of
    /// life, and the long testing periods.
    #[allow(clippy::too_many_arguments)]
    pub fn future(
        &self,
        birth: ExactInstant,
        birth_lat: f64,
        birth_lon: f64,
        lat: f64,
        lon: f64,
        system: HouseSystem,
        ayanamsa: AyanamsaChoice,
        at: ExactInstant,
        months: u32,
        lang: String,
        focus: Vec<String>,
    ) -> Result<Vec<FutureEventRecord>, KshanaError> {
        let natal = self.natal(birth, birth_lat, birth_lon, system, ayanamsa)?;
        let obs = Observer { latitude_deg: lat, longitude_deg: lon, height_m: 0.0 };
        let mut f = focus_of(&focus);
        if f.is_empty() {
            f = kshana_rules::Life::ALL.to_vec();
        }
        let ev = kshana_rules::future::future(&self.spk, self.eop.as_ref(), &natal, &obs, ayanamsa.into(), at.into(), months as usize, &f, kshana_rules::Lang::parse(&lang))
            .map_err(|e| KshanaError::Engine(format!("{e:?}")))?;
        Ok(ev
            .into_iter()
            .map(|e| FutureEventRecord {
                from: e.from.into(),
                to: e.to.into(),
                life: e.life.map(|l| l.name().to_string()),
                kind: e.kind.to_string(),
                headline: e.headline,
                detail: e.detail,
                strength: e.strength * 100.0,
                peak: e.peak.map(Into::into),
            })
            .collect())
    }
}

/// What a question asks the app to do.
#[derive(Clone, Debug, uniffi::Record)]
#[allow(missing_docs)]
pub struct AskActionRecord {
    /// `ask`, `life`, `outlook`, `future`, `remedy`, `fear`, `us`, `plan`, `past`.
    pub kind: String,
    pub life: Option<String>,
    pub topic: Option<String>,
    pub question: Option<String>,
    /// For `outlook`: day, week, month, year. For `plan`: the purpose key.
    pub detail: Option<String>,
}

/// One question the app can answer, offered when it was not sure.
#[derive(Clone, Debug, uniffi::Record)]
#[allow(missing_docs)]
pub struct AskAlternativeRecord {
    pub label: String,
    pub action: AskActionRecord,
}

/// How a question in the person's own words was understood.
#[derive(Clone, Debug, uniffi::Record)]
#[allow(missing_docs)]
pub struct UnderstandingRecord {
    /// `answer`, `choose`, `outside`, `care`.
    pub status: String,
    pub action: Option<AskActionRecord>,
    pub message: String,
    pub alternatives: Vec<AskAlternativeRecord>,
    pub confidence: f64,
    pub reason: String,
}

fn action_record(a: &kshana_rules::understand::Action) -> AskActionRecord {
    use kshana_rules::understand::Action as A;
    let r = |kind: &str| AskActionRecord { kind: kind.into(), life: None, topic: None, question: None, detail: None };
    match a {
        A::Ask { life, topic, question } => AskActionRecord { kind: "ask".into(), life: Some(life.name().into()), topic: topic.map(Into::into), question: Some((*question).into()), detail: None },
        A::Life(l) => AskActionRecord { life: Some(l.name().into()), ..r("life") },
        A::Outlook(s) => AskActionRecord { detail: Some((*s).into()), ..r("outlook") },
        A::Future => r("future"),
        A::Remedy(l) => AskActionRecord { life: l.map(|x| x.name().into()), ..r("remedy") },
        A::ChartFear => r("fear"),
        A::Us => r("us"),
        A::Plan(p) => AskActionRecord { detail: Some((*p).into()), ..r("plan") },
        A::Past => r("past"),
    }
}

/// Understand a question typed or spoken in the person's own words (English, Malayalam
/// or Hindi, in their own scripts or in Latin letters). It answers only when it
/// understood; otherwise it says so and offers the closest questions it can answer.
#[uniffi::export]
pub fn understand(text: String) -> UnderstandingRecord {
    let u = kshana_rules::understand::understand(&text);
    UnderstandingRecord {
        status: u.status.into(),
        action: u.action.as_ref().map(action_record),
        message: u.message,
        alternatives: u.alternatives.iter().map(|a| AskAlternativeRecord { label: a.label.clone(), action: action_record(&a.action) }).collect(),
        confidence: u.confidence,
        reason: u.reason.into(),
    }
}

/// The chart reason behind remedies for `planet` (an engine key such as "Saturn"),
/// pressing through `source` (`dasha`, `gochara` or `natal`) on `life` (a life name, or
/// none for life in general). Shown only when the person taps "How this helps".
#[uniffi::export]
pub fn remedy_how_it_helps(planet: String, source: String, life: Option<String>) -> String {
    let g = match planet.trim() {
        "Sun" => DashaLord::Sun,
        "Moon" => DashaLord::Moon,
        "Mars" => DashaLord::Mars,
        "Mercury" => DashaLord::Mercury,
        "Jupiter" => DashaLord::Jupiter,
        "Venus" => DashaLord::Venus,
        "Saturn" => DashaLord::Saturn,
        "Rahu" => DashaLord::Rahu,
        "Ketu" => DashaLord::Ketu,
        _ => return String::new(),
    };
    let life = life.and_then(|n| kshana_rules::Life::ALL.iter().copied().find(|l| l.name().eq_ignore_ascii_case(n.trim())));
    kshana_rules::remedy_tree::how_it_helps(g, &source, life)
}

fn past_check_record(x: kshana_rules::PastCheck) -> PastCheckRecord {
    PastCheckRecord { from: x.from.into(), to: x.to.into(), life: x.life.name().to_string(), question: x.question, statement: x.statement, good: x.good, strength: x.strength }
}
